-- Generated by drizzle-kit, then edited by hand (ADR-023): the triggers at the end are not in the
-- schema, since drizzle-kit does not model them; append-only.workerd.test.ts lists them after
-- every migration.
--
-- The activity log (ADR-037). A line is never changed and never replaced by its id. It is deleted
-- only once it is older than the retention its site's definition holds in `audit.retentionDays`,
-- 30 to 3650 days; a site with none keeps every line. The bounds are checked here again, so a
-- definition written around the operations still cannot shorten the log below 30 days.
CREATE TABLE `audit_log` (
	`id` text PRIMARY KEY NOT NULL,
	`site_id` text NOT NULL,
	`action` text NOT NULL,
	`outcome` text NOT NULL,
	`error_code` text,
	`actor_kind` text NOT NULL,
	`actor_user_id` text,
	`actor_token_id` text,
	`actor_client_id` text,
	`actor_meta` text,
	`target_type` text,
	`target_id` text,
	`detail` text,
	`request_id` text,
	`ip_hash` text,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL,
	FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "audit_log_outcome" CHECK("audit_log"."outcome" IN ('ok', 'denied', 'failed')),
	CONSTRAINT "audit_log_actor_kind" CHECK("audit_log"."actor_kind" IN ('user', 'token', 'oauth_client', 'system')),
	CONSTRAINT "audit_log_json" CHECK(("audit_log"."actor_meta" IS NULL OR json_valid("audit_log"."actor_meta")) AND ("audit_log"."detail" IS NULL OR json_valid("audit_log"."detail"))),
	CONSTRAINT "audit_log_sizes" CHECK(length("audit_log"."action") <= 64 AND ("audit_log"."detail" IS NULL OR length("audit_log"."detail") <= 2000) AND ("audit_log"."actor_meta" IS NULL OR length("audit_log"."actor_meta") <= 2000))
);
--> statement-breakpoint
CREATE INDEX `audit_log_site_time` ON `audit_log` (`site_id`,`created_at`,`id`);--> statement-breakpoint
CREATE INDEX `audit_log_actor` ON `audit_log` (`site_id`,`actor_user_id`,`created_at`);--> statement-breakpoint
CREATE INDEX `audit_log_target` ON `audit_log` (`site_id`,`target_type`,`target_id`,`created_at`);--> statement-breakpoint
CREATE UNIQUE INDEX `audit_log_id_site` ON `audit_log` (`id`,`site_id`);

--> statement-breakpoint
CREATE TRIGGER `audit_log_immutable`
BEFORE UPDATE ON `audit_log`
BEGIN
	SELECT RAISE(ABORT, 'append-only: a line of the activity log never changes');
END;
--> statement-breakpoint
CREATE TRIGGER `audit_log_no_replace`
BEFORE INSERT ON `audit_log`
WHEN EXISTS (SELECT 1 FROM `audit_log` WHERE `id` = NEW.`id`)
BEGIN
	SELECT RAISE(ABORT, 'append-only: a line of the activity log is written once');
END;
--> statement-breakpoint
CREATE TRIGGER `audit_log_no_delete`
BEFORE DELETE ON `audit_log`
WHEN NOT EXISTS (
	SELECT 1 FROM `sites`
	WHERE `id` = OLD.`site_id`
		AND json_valid(`definition`)
		AND json_type(`definition`, '$.audit.retentionDays') = 'integer'
		AND json_extract(`definition`, '$.audit.retentionDays') BETWEEN 30 AND 3650
		AND OLD.`created_at` < strftime('%Y-%m-%dT%H:%M:%fZ', 'now', '-' || json_extract(`definition`, '$.audit.retentionDays') || ' days')
)
BEGIN
	SELECT RAISE(ABORT, 'append-only: a line of the activity log is kept for the retention of its site');
END;
